_DOCS_DIR = "/app/docs-public"


def _serve_doc(filename: str, not_found_detail: str):
    """Serve one named file from docs-public (a fixed allowlist of names below, never a path taken from the request)."""
    from fastapi.responses import FileResponse
    path = os.path.join(_DOCS_DIR, filename)
    if not os.path.exists(path):
        raise HTTPException(status_code=404, detail=not_found_detail)
    return FileResponse(path, media_type="text/html")


