def _infer_scan_engine_label(cve_id: str, scan_engine: Optional[str]) -> str:
    """Maps a finding to a human-readable scanner name. Prefers the scan_engine
    column; many older auditors don't set it, so falls back to the cve_id prefix
    convention used across auditors/*.py."""
    engine_labels = {
        "prowler": "Cloud CSPM (Prowler)",
        "sca-license": "Licencias de dependencias (Syft)",
        "api-contract": "Contrato de API (rutas vs OpenAPI)",
        "dns-security": "DNS y correo (SPF/DMARC)",
        "semgrep": "SAST (Semgrep)",
        "zap": "DAST (OWASP ZAP)",
        "secrets": "Secretos (TruffleHog)",
        "spiderfoot": "OSINT (SpiderFoot)",
        "ffuf": "API Discovery (ffuf)",
        "kiterunner": "API Discovery (Kiterunner)",
        "standards-audit": "Estándares (STRIDE / ISO 25010)",
        "bloodhound": "Rutas de Ataque AD (BloodHound)",
        "cis-benchmark": "Hardening (CIS Benchmarks)",
        "os-patch": "Parches y EOL del SO",
        "tls-audit": "Postura TLS / Certificados",
        "gitlab-config": "Configuración GitLab y CI/CD",
        "wstg-perimeter": "Perímetro Web (OWASP WSTG)",
    }
    if scan_engine and scan_engine in engine_labels:
        return engine_labels[scan_engine]
    cve = (cve_id or "").upper()
    prefix_labels = [
        ("SCAN-AUDIT", "Auditoría Interna (multi-motor)"),
        ("HEURISTIC-", "Motor de Heurísticas SOAR"),
        ("NMAP-", "Descubrimiento de Puertos (Nmap)"),
        ("TECH-", "Detección de Tecnología (Nuclei)"),
        ("STD-", "Estándares (STRIDE / ISO 25010)"),
        ("DOCKER-", "Contenedores (Trivy)"),
        ("BLOODHOUND", "Rutas de Ataque AD (BloodHound)"),
        ("WAZUH-", "EDR (Wazuh)"),
        ("OSINT-", "OSINT (SpiderFoot)"),
        ("SECRETS-", "Secretos (TruffleHog)"),
        ("ZAP-", "DAST (OWASP ZAP)"),
        ("CVE-", "CVE Conocido (Trivy / Nuclei)"),
    ]
    for prefix, label in prefix_labels:
        if cve.startswith(prefix):
            return label
    if scan_engine:
        return scan_engine.title()
    return "Nuclei (Plantillas Web)"



def _render_cmmi_practice_areas_html(practice_areas: list) -> str:
    # Real bug fixed 2026-08-25: pa["passed"] can now be None (the CM practice area's genuine
    # N/A state for non-repository assets, see compliance_mapper.py) -- Python treats None as
    # falsy, so the old ternary rendered an N/A area with the same red "card-crit"/"badge-critical"
    # styling as a real failure, misrepresenting "doesn't apply" as "failed". card-warn/badge-info
    # (already-defined neutral styles used elsewhere in this file) render the N/A case correctly.
    def _card_cls(passed):
        return "card-ok" if passed is True else "card-crit" if passed is False else "card-warn"

    def _badge_cls(passed):
        return "badge-low" if passed is True else "badge-critical" if passed is False else "badge-info"

    rows = "".join([
        f"""<div class='card {_card_cls(pa["passed"])}' style='margin-bottom:8px;'>
              <div style='display:flex;justify-content:space-between;align-items:center;margin-bottom:4px;'>
                <h3 style='margin:0;'>{pa['area']}</h3>
                <span class='badge {_badge_cls(pa["passed"])}'>{pa['status']}</span>
              </div>
              <div style='font-size:9px;color:#475569;'>{pa['evidence']}</div>
            </div>"""
        for pa in practice_areas
    ])
    return rows



