# Reportes por grupo (core/group_reports.py): reporte general consolidado y paquete ZIP con todos los reportes del grupo.
class GroupSelection(BaseModel):
    asset: List[str] = []
    prefix: Optional[str] = None
    title: Optional[str] = None


def _resolve_group(asset: List[str], prefix: Optional[str]):
    from core import scan_comparison, group_reports
    if len(asset) > group_reports.BUNDLE_MAX_ASSETS:
        raise HTTPException(status_code=400, detail=f"Máximo {group_reports.BUNDLE_MAX_ASSETS} activos")
    with db_manager.get_db_cursor() as cur:
        try:
            assets = scan_comparison.resolve_assets(cur, asset, prefix)
        except ValueError as e:
            raise HTTPException(status_code=400, detail=str(e))
    if not assets:
        raise HTTPException(status_code=404, detail="Ningún activo coincide")
    if any(not access_scope.allows(a["name"]) for a in assets):        # ADR-0019: a group may not reach outside the caller's projects
        raise HTTPException(status_code=403, detail="Acceso denegado: la selección incluye activos fuera de su alcance.")
    if len(assets) > group_reports.BUNDLE_MAX_ASSETS:
        raise HTTPException(status_code=400, detail=f"{len(assets)} activos coinciden; acote el grupo (máximo {group_reports.BUNDLE_MAX_ASSETS})")
    return assets


def _group_general_html(assets, title: str) -> str:
    from core import group_reports
    with db_manager.get_db_cursor() as cur:
        summary = group_reports.group_summary(cur, [a["id"] for a in assets])
    return group_reports.render_group_general_html(title, summary)


def _group_comparison_html(assets, title: str) -> str:
    from core import scan_comparison
    with db_manager.get_db_cursor() as cur:
        comps = scan_comparison.compare_assets(cur, [a["id"] for a in assets])
    return scan_comparison.render_html(comps, title)


@router.get("/api/reports/group/general")
def download_group_general_report(asset: List[str] = Query(default=[]), prefix: Optional[str] = None,
                                  title: Optional[str] = None, format: str = "pdf"):
    """Reporte general consolidado de un grupo de activos (nombres exactos y/o prefijo). format = pdf | html | json."""
    from core import group_reports
    assets = _resolve_group(asset, prefix)
    label = title or prefix or f"{len(assets)} activos"
    fmt = (format or "pdf").lower()
    if fmt == "json":
        with db_manager.get_db_cursor() as cur:
            s = group_reports.group_summary(cur, [a["id"] for a in assets])
        for r in s["assets"]:
            r["last_audit"] = str(r["last_audit"]) if r["last_audit"] else None
        return JSONResponse(content=s)
    html_content = _group_general_html(assets, f"Reporte general — {label}")
    if fmt == "html":
        return HTMLResponse(content=html_content)
    safe = re.sub(r"[^A-Za-z0-9._-]+", "_", label).strip("_")[:120] or "grupo"
    return Response(content=render_pdf_with_weasyprint(html_content), media_type="application/pdf",
                    headers={"Content-Disposition": f'attachment; filename="Reporte_general_{safe}_{datetime.now():%Y-%m-%d}.pdf"'})


def _asset_pdf_bytes(asset_name: str) -> bytes:
    resp = download_asset_report(asset_name, "pdf")
    if getattr(resp, "media_type", "") != "application/pdf":
        raise RuntimeError("el reporte del activo no se pudo generar como PDF")
    return resp.body


@router.post("/api/reports/group/bundle")
def start_group_bundle(sel: GroupSelection):
    """Arma en segundo plano un ZIP con: reporte general del grupo, comparativo del grupo y el reporte de cada activo.
    Devuelve bundle_id; consultar /api/reports/group/bundle/{id} y descargar /api/reports/group/bundle/{id}/download."""
    from core import group_reports
    assets = _resolve_group(sel.asset, sel.prefix)
    label = sel.title or sel.prefix or f"{len(assets)} activos"
    try:
        bundle_id = group_reports.start_bundle(
            label, assets,
            render_group_pdf=lambda: render_pdf_with_weasyprint(_group_general_html(assets, f"Reporte general — {label}")),
            render_comparison_pdf=lambda: render_pdf_with_weasyprint(_group_comparison_html(assets, f"Comparativo de remediación — {label}")),
            render_asset_pdf=_asset_pdf_bytes)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    try:
        agent_ledger.record_action("report_bundle", f"Paquete de reportes '{label}' ({len(assets)} activos)",
                                   entity_type="report_bundle", entity_id=bundle_id, actor="dashboard")
    except Exception:
        logging.getLogger(__name__).error("ledger write failed", exc_info=True)
    return {"bundle_id": bundle_id, "assets": len(assets), "title": label}


@router.get("/api/reports/group/bundle/{bundle_id}")
def group_bundle_status(bundle_id: str):
    from core import group_reports
    st = group_reports.get_status(bundle_id)
    if not st:
        raise HTTPException(status_code=404, detail="Paquete no encontrado (expiran a las 24 h)")
    return st


@router.get("/api/reports/group/bundle/{bundle_id}/download")
def download_group_bundle(bundle_id: str):
    from core import group_reports
    path = group_reports.zip_path(bundle_id)
    if not path:
        raise HTTPException(status_code=404, detail="El paquete no está listo o ya expiró")
    return FileResponse(path, media_type="application/zip", filename=os.path.basename(path))


# ---------------------------------------------------------------------------------------------------- SBOM (ADR-0022 §6)
@router.get("/api/reports/sbom", summary="SBOM CycloneDX de un activo",
            description="Descarga el inventario de componentes (CycloneDX) generado en el último escaneo del activo. "
                        "404 si el activo no tiene SBOM (aún no se escanea, o es un ZIP subido).",
            responses={200: {"description": "Documento CycloneDX JSON"}, 403: {"description": "Activo fuera de su alcance"},
                       404: {"description": "Sin SBOM para ese activo"}})
def download_sbom(asset_name: str):
    from auditors import sbom_export
    if not access_scope.allows(asset_name):
        raise HTTPException(status_code=403, detail="Activo fuera de su alcance")
    path = sbom_export.sbom_path(asset_name)
    if not os.path.isfile(path):
        raise HTTPException(status_code=404, detail="Este activo no tiene SBOM todavía (se genera en su próximo escaneo GitLab)")
    return FileResponse(path, media_type="application/vnd.cyclonedx+json",
                        filename=re.sub(r"[^A-Za-z0-9._-]+", "_", asset_name)[:100] + ".cdx.json")


@router.get("/api/reports/sbom/component", summary="¿Qué activos usan un componente?",
            description="Busca un componente (nombre exacto, con grupo opcional `org.example/lib`) en los SBOM guardados. "
                        "Solo devuelve activos dentro del alcance de quien consulta.",
            responses={200: {"description": "Lista de activos con el componente y su versión"}})
def find_sbom_component(name: str, version: Optional[str] = None):
    from auditors import sbom_export
    hits = [h for h in sbom_export.find_component(name, version) if access_scope.allows(h["asset"])]
    return {"component": name, "version": version, "matches": hits, "assets": len({h["asset"] for h in hits})}
